    for (final worker in _workers) {
      if (worker.state != _WorkerState.dead) {
        worker.sendPort.send(_shutdownMessage);
      }
    }
    _workers.clear();
    _jobs.clear();
    _completed.clear();
    _exitPort?.close();
    _exitPort = null;
